const files = $input.all();
let totalSize = 0;
let backupCount = 0;
const backups = [];

if (Array.isArray(files)) {
  files.forEach(file => {
    if (file.json && file.json.Key) {
      const key = file.json.Key;
      const size = file.json.Size || 0;

      // Фильтруем только файлы бэкапов (*.sql.gz, *.dump, etc)
      if (key.match(/\.(sql\.gz|dump|tar\.gz|zip)$/i)) {
        totalSize += size;
        backupCount += 1;
        backups.push({
          key: key,
          size: size,
          lastModified: file.json.LastModified
        });
      }
    }
  });
}

return {
  json: {
    total_backups_size: totalSize,
    backups_count: backupCount,
    backups_list: backups.slice(0, 10) // Последние 10 для справки
  }
};

// Получаем результаты параллельных выполнений
const postgresResult = $item(0);
const s3Result = $item(1);

let postgresData = {};
let s3Data = {};

if (postgresResult?.json && Array.isArray(postgresResult.json) && postgresResult.json[0]) {
  postgresData = postgresResult.json[0];
} else if (postgresResult?.json) {
  postgresData = postgresResult.json;
}

if (s3Result?.json) {
  s3Data = s3Result.json;
}

// Агрегируем данные
const aggregated = {
  total_backups_size: s3Data.total_backups_size || 0,
  backups_count: s3Data.backups_count || 0,
  db_tables_count: postgresData.db_tables_count || 0,
  indexes_size: postgresData.indexes_size || 0,
  active_connections: postgresData.active_connections || 0,
  db_size: postgresData.db_size || 0,
  timestamp: new Date().toISOString()
};

console.log('Aggregated analytics data:', aggregated);

return { json: aggregated };
